import path from 'node:path';

const ROOT = path.resolve('/srv/uploads');

export function download(req, res) {
  const target = path.resolve(ROOT, req.params.name);
  if (!target.startsWith(ROOT + path.sep)) return res.status(400).end();
  res.sendFile(target);
}

